SELECT      TRUNC(SYSDATE)                                       AS \"Report Date\",      woh.WF_ORDER_NO                                      AS \"Store Order Number\",     woh.ORDER_TYPE                                       AS \"Order Type Code\",     CASE woh.ORDER_TYPE         WHEN 'W' THEN 'Warehouse Replenishment'         WHEN 'S' THEN 'Supplier Direct'         WHEN 'T' THEN 'Transfer'         WHEN 'F' THEN 'Franchise Order'         ELSE woh.ORDER_TYPE     END                                                  AS \"Order Type Description\",     woh.STATUS                                           AS \"Order Status Code\",     CASE woh.STATUS         WHEN 'W' THEN 'Worksheet'         WHEN 'S' THEN 'Submitted'         WHEN 'A' THEN 'Approved'         WHEN 'C' THEN 'Closed'         ELSE woh.STATUS     END                                                  AS \"Order Status Description\",     woh.CURRENCY_CODE                                    AS \"Currency Code\",     woh.APPROVAL_DATE                                    AS \"Approval Date\",     woh.COMMENTS                                         AS comments,     woh.CREATE_ID                                        AS \"Created By\",      wod.CUSTOMER_LOC                                     AS \"Store ID\",     st.STORE_NAME                                        AS \"Store Name\",     st.STORE_TYPE                                        AS \"Store Type Code\",     CASE st.STORE_TYPE         WHEN 'C' THEN 'Company'         WHEN 'F' THEN 'Franchise'         ELSE st.STORE_TYPE     END                                                  AS \"Store Type Description\",      so.DELIVERY_SLOT_ID                                  AS \"Delivery Slot ID\",     ds.DELIVERY_SLOT_DESC                                AS \"Delivery Slot Description\",      wod.SOURCE_LOC_ID                                    AS \"Source Location ID\",     wod.SOURCE_LOC_TYPE                                  AS \"Source Location Type\",     CASE wod.SOURCE_LOC_TYPE         WHEN 'W' THEN wh.WH_NAME         WHEN 'S' THEN src_st.STORE_NAME     END                                                  AS \"Source Location Name\",      wod.ITEM                                             AS \"Item ID\",     im.ITEM_DESC                                         AS \"Item Description\",     im.DEPT                                              AS \"Department Number\",     d.DEPT_NAME                                          AS \"Department Name\",     im.CLASS                                             AS \"Class Number\",     c.CLASS_NAME                                         AS \"Class Name\",     im.SUBCLASS                                          AS \"Subclass Number\",     sc.SUB_NAME                                          AS \"Subclass Name\",     im.STANDARD_UOM                                      AS \"Unit of Measure\",      oh.SUPPLIER                                          AS \"Supplier ID\",     sp.SUP_NAME                                          AS \"Supplier Name\",      wod.REQUESTED_QTY                                    AS \"Quantity Ordered\",     wod.NEED_DATE                                        AS \"Need Date\",     wod.NOT_AFTER_DATE                                   AS \"Not After Date\",     woh.CREATE_DATETIME                                  AS \"Order Date\",     TRUNC(SYSDATE) - TRUNC(woh.CREATE_DATETIME)         AS \"Days Since Order\",      ril.REPL_METHOD                                      AS \"Replenishment Method\",     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'F'  THEN 'Floating Point'         ELSE ril.REPL_METHOD     END                                                  AS \"Replenishment Method Description\",     ril.STOCK_CAT                                        AS \"Stock Category\",      wod.ACQUISITION_COST                                 AS \"Acquisition Cost\",     wod.CUSTOMER_COST                                    AS \"Customer Cost\",     ils.UNIT_COST                                        AS \"Unit Cost\",     il.UNIT_RETAIL                                       AS \"Unit Retail\",     ROUND(NVL(wod.REQUESTED_QTY, 0) * ils.UNIT_COST, 2) AS \"Total Order Cost\",     ROUND(NVL(wod.REQUESTED_QTY, 0) * il.UNIT_RETAIL, 2) AS \"Total Order Retail\",      th.TSF_NO                                            AS \"Transfer Number\",     th.STATUS                                            AS \"Transfer Status\",      ils.STOCK_ON_HAND                                    AS \"Current Stock on Hand\",     ils.AV_COST                                          AS \"Weighted Average Cost\"  FROM     MFCS_RDS.RDS_WV_WF_ORDER_HEAD           woh      JOIN  MFCS_RDS.RDS_WV_WF_ORDER_DETAIL   wod   ON  woh.WF_ORDER_NO     = wod.WF_ORDER_NO      LEFT JOIN MFCS_RDS.RDS_WV_STORE          st   ON  wod.CUSTOMER_LOC    = st.STORE      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER        im   ON  wod.ITEM             = im.ITEM      JOIN  MFCS_RDS.RDS_WV_DEPS               d    ON  im.DEPT              = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS              c    ON  im.DEPT              = c.DEPT                                                    AND im.CLASS             = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS           sc   ON  im.DEPT              = sc.DEPT                                                    AND im.CLASS             = sc.CLASS                                                    AND im.SUBCLASS          = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC       il   ON  wod.ITEM             = il.ITEM                                                    AND wod.CUSTOMER_LOC    = il.LOC                                                    AND il.LOC_TYPE          = 'S'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH   ils  ON  wod.ITEM             = ils.ITEM                                                    AND wod.CUSTOMER_LOC    = ils.LOC                                                    AND ils.LOC_TYPE         = 'S'      LEFT JOIN MFCS_RDS.RDS_WV_REPL_ITEM_LOC  ril  ON  wod.ITEM             = ril.ITEM                                                    AND wod.CUSTOMER_LOC    = ril.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_STORE_ORDERS   so   ON  woh.WF_ORDER_NO      = so.WF_ORDER_NO                                                    AND wod.ITEM             = so.ITEM                                                    AND wod.CUSTOMER_LOC    = so.STORE      LEFT JOIN MFCS_RDS.RDS_WV_DELIVERY_SLOT  ds   ON  so.DELIVERY_SLOT_ID  = ds.DELIVERY_SLOT_ID      LEFT JOIN MFCS_RDS.RDS_WV_WH             wh   ON  wod.SOURCE_LOC_ID    = wh.WH                                                    AND wod.SOURCE_LOC_TYPE  = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_STORE          src_st ON wod.SOURCE_LOC_ID   = src_st.STORE                                                    AND wod.SOURCE_LOC_TYPE  = 'S'      LEFT JOIN MFCS_RDS.RDS_WV_TSFHEAD        th   ON  so.WF_ORDER_LINE_NO  = th.TSF_NO      LEFT JOIN MFCS_RDS.RDS_WV_ORDHEAD         oh  ON  woh.WF_ORDER_NO      = oh.ORDER_NO     LEFT JOIN MFCS_RDS.RDS_WV_SUPS            sp  ON  oh.SUPPLIER          = sp.SUPPLIER   ORDER BY     st.STORE_NAME,     woh.CREATE_DATETIME DESC,     woh.WF_ORDER_NO,     im.ITEM_DESC</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Report Date</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds:column><ds:name>Store Order Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Order Type Code</ds:name><ds:datatype>varchar(1)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Order Type Description</ds:name><ds:datatype>varchar(23)</ds:datatype></ds:column><ds:column><ds:name>Order Status Code</ds:name><ds:datatype>varchar(1)</ds:datatype>